ALTER TABLE public.services ADD COLUMN IF NOT EXISTS summary text;
ALTER TABLE public.services ADD COLUMN IF NOT EXISTS summary_en text;

UPDATE public.services SET summary = $t$Дитяча стоматологія Зубна Фея у Білій Церкві приймає малюків, школярів і підлітків. Лікар спершу знайомить дитину з кабінетом, потім проводить огляд, профілактику та за потреби лікує молочні й постійні зуби. Тут лікують карієс і пульпіт, ставлять дитячі коронки, видаляють молочні зуби, а для дітей зі сильним страхом можливе лікування під седацією або наркозом.$t$, summary_en = $t$Tooth Fairy pediatric dentistry in Bila Tserkva treats toddlers, school-age children and teenagers. The dentist first lets the child get used to the room, then examines the teeth, provides preventive care and treats baby and permanent teeth when needed. Services include cavity and pulpitis treatment, children's crowns and baby tooth extraction, with sedation or general anaesthesia for very anxious children.$t$ WHERE id = '2ea61115-67b4-4b99-8b39-9e19e68c101e';
UPDATE public.services SET summary = $t$Терапевтична стоматологія - базове лікування зубів у дорослих у клініці Зубна Фея в Білій Церкві. Стоматолог-терапевт з'ясовує причину чутливості, болю чи незручності під час жування, лікує карієс, замінює старі пломби, відновлює сколи й пошкоджені зуби. Огляд охоплює сусідні зуби, реставрації та ясна, тому лікування починають із точної діагностики.$t$, summary_en = $t$General dentistry at Tooth Fairy in Bila Tserkva covers everyday dental treatment for adults. The dentist finds the cause of sensitivity, pain or discomfort when chewing, treats cavities, replaces old fillings and repairs chipped or damaged teeth. The examination includes neighbouring teeth, existing restorations and gums, so treatment always starts with an accurate diagnosis.$t$ WHERE id = '7a0dc235-4755-4a33-9081-32f9dd0bd6f9';
UPDATE public.services SET summary = $t$Консультація стоматолога в клініці Зубна Фея у Білій Церкві - перший крок, якщо болить зуб, кровлять ясна або давно не було огляду. Лікар вислуховує скарги, збирає анамнез, оглядає зуби, пломби, ясна, слизову та прикус, за потреби призначає знімок. Наприкінці пацієнт отримує зрозумілий план: що лікувати, в якій послідовності, або підтвердження, що лікування не потрібне.$t$, summary_en = $t$A dental consultation at Tooth Fairy in Bila Tserkva is the first step when a tooth hurts, gums bleed or a check-up is due. The dentist listens to your concerns, takes a medical history, examines teeth, fillings, gums and bite, and orders an X-ray if needed. You leave with a clear treatment plan or confirmation that none is needed.$t$ WHERE id = 'f1f8b7da-6771-4ac5-9af4-cb7158f83c24';
UPDATE public.services SET summary = $t$Імплантація зубів у клініці Зубна Фея в Білій Церкві відновлює втрачений зуб без обточування сусідніх. Імплант встановлюють у кістку замість кореня, а після загоєння фіксують коронку, підібрану за формою та відтінком. Лікування починають із консультації, діагностики та цифрового планування; імпланти підходять при втраті одного, кількох або всіх зубів.$t$, summary_en = $t$Dental implants at Tooth Fairy in Bila Tserkva replace a missing tooth without grinding down the neighbouring teeth. The implant is placed in the bone in place of the root, and after healing a crown matched in shape and shade is attached. Treatment starts with a consultation, imaging and digital planning, for one, several or all missing teeth.$t$ WHERE id = '831d0d69-1b94-4791-88a5-121c345b60c8';
UPDATE public.services SET summary = $t$Ендодонтичне лікування в клініці Зубна Фея у Білій Церкві - лікування пульпіту, періодонтиту та складних кореневих каналів під мікроскопом. Лікар видаляє уражені тканини, очищає й дезінфікує канали та герметично їх пломбує. Мета - зупинити інфекцію, прибрати біль і зберегти власний зуб, якщо клінічна ситуація це дозволяє.$t$, summary_en = $t$Root canal treatment at Tooth Fairy in Bila Tserkva treats pulpitis, periodontitis and complex root canals under a microscope. The dentist removes infected tissue, cleans and disinfects the canals and seals them tightly. The aim is to stop the infection, relieve pain and save your natural tooth whenever the clinical situation allows.$t$ WHERE id = 'adb69206-ca61-499e-be74-9a5e20b0ece9';
UPDATE public.services SET summary = $t$Ортодонтія в клініці Зубна Фея у Білій Церкві виправляє нерівні зуби, проміжки, скупченість і неправильне змикання щелеп у дітей, підлітків і дорослих. Ортодонт вивчає прикус, знімки та положення щелеп і підбирає апарат: металеві, керамічні чи самолігуючі брекети, елайнери або пластинки. Дітей варто показати лікарю в період зміни зубів.$t$, summary_en = $t$Orthodontics at Tooth Fairy in Bila Tserkva corrects crooked teeth, gaps, crowding and an incorrect bite in children, teenagers and adults. The orthodontist studies the bite, X-rays and jaw position, then chooses the appliance: metal, ceramic or self-ligating braces, clear aligners or removable plates. Children are best assessed while their teeth are changing.$t$ WHERE id = 'bdf1e15a-49e8-4c0e-9605-2c18a21a46f4';
UPDATE public.services SET summary = $t$Консультант з грудного вигодовування в клініці Зубна Фея у Білій Церкві допомагає, коли годування болить або немовля не може правильно прикластися до грудей. Спеціаліст оцінює захват груди, рухи язика та тривалість годування і перевіряє вуздечку язика й губи. Якщо вуздечка вкорочена, консультант разом із дитячим стоматологом пояснює, як це виправити.$t$, summary_en = $t$The breastfeeding consultant at Tooth Fairy in Bila Tserkva helps when feeding is painful or a baby cannot latch properly. The specialist assesses the latch, tongue movement and feeding duration and checks the tongue and lip ties. If a tie is too short, the consultant and the paediatric dentist explain how it can be corrected.$t$ WHERE id = '66dc34a7-232d-4a19-b30b-c2b412e7afd9';
UPDATE public.services SET summary = $t$Лікування зубів під наркозом у клініці Зубна Фея в Білій Церкві - для дітей і дорослих, яким сильний страх чи стан здоров'я не дають пройти звичайний прийом, або коли потрібно виконати багато роботи за один раз. Пацієнт спить і не відчуває процедур. Стоматолог лікує зуби, а анестезіолог контролює дихання, тиск і пульс.$t$, summary_en = $t$Dental treatment under general anaesthesia at Tooth Fairy in Bila Tserkva is for children and adults who cannot manage a regular appointment because of severe fear or health conditions, or who need extensive work in one visit. The patient sleeps and feels nothing. The dentist treats the teeth while an anaesthetist monitors breathing, blood pressure and pulse.$t$ WHERE id = '819cb2aa-956b-4e07-8019-dd373485dd15';
UPDATE public.services SET summary = $t$Стоматологічна хірургія в клініці Зубна Фея у Білій Церкві - видалення зубів, зокрема ретинованих і дистопованих зубів мудрості, та інші хірургічні втручання за показаннями. Перед процедурою хірург вивчає знімок, оцінює корені, нерви й кістку та пояснює кожен етап. Якщо дозволяє стан пацієнта, кілька зубів мудрості можна видалити за один візит.$t$, summary_en = $t$Oral surgery at Tooth Fairy in Bila Tserkva covers tooth extractions, including impacted and misaligned wisdom teeth, and other procedures when clinically indicated. Before surgery the surgeon studies the X-ray, assesses the roots, nerves and bone and explains every step. When your health allows, several wisdom teeth can be removed in one visit.$t$ WHERE id = '2e0f0583-17a1-4fe1-872d-b16f5aa76f57';
UPDATE public.services SET summary = $t$Ортопедія в клініці Зубна Фея у Білій Церкві повертає зубам форму, вигляд і жувальну функцію. Лікар-ортопед відновлює зруйновані або втрачені зуби коронками, мостами, вінірами та протезами, які виготовляють індивідуально під прикус конкретного пацієнта. Перед протезуванням оцінюють корені, ясна та навантаження, щоб конструкція виглядала природно й служила довго.$t$, summary_en = $t$Prosthodontics at Tooth Fairy in Bila Tserkva restores the shape, appearance and chewing function of teeth. The prosthodontist rebuilds damaged or missing teeth with crowns, bridges, veneers and dentures made individually for each patient's bite. Roots, gums and chewing load are assessed first so the restoration looks natural and lasts.$t$ WHERE id = 'b69865ce-d3c2-4e0a-8191-0b96428b19b6';
UPDATE public.services SET summary = $t$Естетична стоматологія в клініці Зубна Фея у Білій Церкві працює з формою, кольором і пропорціями зубів, щоб усмішка виглядала природно. Лікар коригує форму зубів, відновлює сколи художньою реставрацією, відбілює емаль і пропонує керамічні вініри. План складають з урахуванням рис обличчя, лінії губ і стану зубів.$t$, summary_en = $t$Cosmetic dentistry at Tooth Fairy in Bila Tserkva improves the shape, colour and proportions of your teeth so your smile looks natural. The dentist reshapes teeth, repairs chips with composite restorations, whitens enamel and offers ceramic veneers. The plan takes into account your facial features, lip line and the health of your teeth.$t$ WHERE id = '580fa779-d1c1-4111-be47-eab3dbb9031a';
UPDATE public.services SET summary = $t$Кабінет діагностики клініки Зубна Фея у Білій Церкві робить КТ зубів і щелеп, панорамні знімки (ОПТГ) і ТРГ. Панорамний знімок показує всю щелепу, приховані карієси та зуби мудрості, а 3D-томографія - кістку, корені й нервові канали в об'ємі. Знімки потрібні для точного плану лікування, видалення, імплантації чи ортодонтії.$t$, summary_en = $t$The diagnostic imaging room at Tooth Fairy in Bila Tserkva provides dental and jaw CT scans, panoramic X-rays (OPG) and cephalometric X-rays. A panoramic image shows the whole jaw, hidden cavities and wisdom teeth, while 3D CT shows bone, roots and nerve canals in detail. Imaging supports precise planning for extractions, implants and orthodontics.$t$ WHERE id = '959ed98e-0b59-4d89-81a5-4b1f43ba0677';
UPDATE public.services SET summary = $t$Сім'ї з Умані привозять дітей до дитячої стоматології Зубна Фея у Білій Церкві. Лікарі спокійно знайомлять дитину з кабінетом, використовують цифрову діагностику та лікують молочні зуби так, щоб зберегти їх до природної зміни. Для дітей, які дуже бояться, доступне лікування уві сні під контролем анестезіолога.$t$, summary_en = $t$Families from Uman bring their children to Tooth Fairy pediatric dentistry in Bila Tserkva. The dentists calmly introduce children to the room, use digital diagnostics and treat baby teeth so they last until they fall out naturally. For very anxious children, treatment during sleep is available under the supervision of an anaesthetist.$t$ WHERE id = '9a1e59ed-bf41-404b-8f54-5a81e9f20505';
UPDATE public.services SET summary = $t$Батьки з Жашкова приїжджають із дітьми до дитячої стоматології Зубна Фея у Білій Церкві. Тут проводять профілактичні огляди й чистку, лікують карієс, консультують щодо прикусу та організовують перший візит для малюків. Лікарі не поспішають і пояснюють усе простими словами, а для дітей зі сильним страхом можливе лікування уві сні.$t$, summary_en = $t$Parents from Zhashkiv bring their children to Tooth Fairy pediatric dentistry in Bila Tserkva. The clinic offers check-ups and cleaning, cavity treatment, bite consultations and a gentle first visit for toddlers. The dentists take their time and explain everything in simple words, and children with strong dental fear can be treated during sleep.$t$ WHERE id = '158bc735-f0db-4f6c-bfad-4fe1c203c7bc';
UPDATE public.services SET summary = $t$Видалення молочного зуба в клініці Зубна Фея у Білій Церкві проводять лише за показаннями: сильне руйнування, біль, запалення, травма або коли молочний зуб заважає прорізуванню постійного. Спершу стоматолог оглядає зуб і корені та перевіряє, чи можна його вилікувати. Дитині дають час звикнути до кабінету й домовляються про сигнал зупинки.$t$, summary_en = $t$Baby tooth extraction at Tooth Fairy in Bila Tserkva is done only when needed: severe decay, pain, infection, injury or when the baby tooth blocks the permanent one. The dentist first examines the tooth and roots and checks whether it can be saved. Children get time to settle in and agree on a stop signal with the dentist.$t$ WHERE id = 'efed2f20-8f6d-4678-bd9f-159684ac89f9';
UPDATE public.services SET summary = $t$Лікування пульпіту у дітей у клініці Зубна Фея в Білій Церкві - це лікування запаленої пульпи молочних і постійних зубів. Лікар оглядає зуб і робить знімок, щоб оцінити глибину запалення, а потім за можливості зберігає живу частину пульпи. Привід звернутися - нічний біль, реакція на тепле або жування одним боком.$t$, summary_en = $t$Pulpitis treatment for children at Tooth Fairy in Bila Tserkva treats inflamed pulp in baby and permanent teeth. The dentist examines the tooth and takes an X-ray to see how deep the inflammation goes, then preserves the healthy part of the pulp whenever possible. Night pain, sensitivity to heat or chewing on one side are reasons to visit.$t$ WHERE id = 'c8c0929c-56f1-4a68-92a7-12a7fd72721e';
UPDATE public.services SET summary = $t$Коронки дітям у клініці Зубна Фея в Білій Церкві ставлять на сильно зруйновані молочні зуби, які ще рано видаляти. Коронка накриває зуб з усіх боків, повертає йому форму та бере на себе жувальне навантаження. Лікар підбирає металеву або цирконієву коронку; при природній зміні зуб випадає разом із нею.$t$, summary_en = $t$Children's crowns at Tooth Fairy in Bila Tserkva are placed on badly damaged baby teeth that are too early to remove. The crown covers the whole tooth, restores its shape and takes the chewing load. The dentist chooses a stainless steel or zirconia crown, and when the time comes the tooth falls out together with it.$t$ WHERE id = '10bcbbb6-5603-4775-9877-bb2e4776761e';
UPDATE public.services SET summary = $t$Лікування карієсу у дітей у клініці Зубна Фея в Білій Церкві зупиняє руйнування молочних і постійних зубів до того, як запалення дійде до пульпи. Лікар визначає глибину ураження, оцінює ризик нових порожнин і обирає спосіб лікування. Карієс у дітей часто не болить, тому важливі регулярні огляди.$t$, summary_en = $t$Cavity treatment for children at Tooth Fairy in Bila Tserkva stops decay in baby and permanent teeth before it reaches the pulp. The dentist checks how deep the decay goes, assesses the risk of new cavities and chooses the treatment method. Cavities in children often cause no pain, so regular check-ups matter.$t$ WHERE id = '3e5da9a1-39c9-410e-95f8-68e959424d10';
UPDATE public.services SET summary = $t$Керамічні брекети в клініці Зубна Фея у Білій Церкві - незнімна ортодонтична система зі світлих замочків, близьких до відтінку емалі. Вони вирівнюють зуби й виправляють прикус так само, як класичні брекети, але менш помітні на розмовній відстані. Ортодонт складає план лікування та регулярно змінює дугу й лігатури.$t$, summary_en = $t$Ceramic braces at Tooth Fairy in Bila Tserkva are a fixed orthodontic system with tooth-coloured brackets close to the shade of enamel. They straighten teeth and correct the bite like classic braces but are less noticeable at conversational distance. The orthodontist plans treatment and regularly adjusts the wire and ligatures.$t$ WHERE id = '0bc6a836-c715-40b7-8bfa-2e1f850022a1';
UPDATE public.services SET summary = $t$Металеві брекети в клініці Зубна Фея у Білій Церкві - класична незнімна система для вирівнювання зубів, закриття проміжків і корекції прикусу. Вона помітна, зате міцна й передбачувана в роботі. Ортодонт складає план за знімками й діагностичними моделями, а на контрольних прийомах змінює дуги та коригує силу.$t$, summary_en = $t$Metal braces at Tooth Fairy in Bila Tserkva are a classic fixed system for straightening teeth, closing gaps and correcting the bite. They are visible but strong and predictable. The orthodontist plans treatment using X-rays and diagnostic models and adjusts the wires and force at follow-up visits.$t$ WHERE id = 'b749db09-855a-4bd7-9e81-a15d0702947b';
UPDATE public.services SET summary = $t$Самолігуючі брекети в клініці Зубна Фея у Білій Церкві - незнімна ортодонтична система, де дугу утримує вбудована кліпса замість окремої лігатури. Вони вирівнюють зуби й виправляють прикус під контролем ортодонта, а корекції на прийомі проходять без заміни лігатур на кожному замочку.$t$, summary_en = $t$Self-ligating braces at Tooth Fairy in Bila Tserkva are a fixed orthodontic system in which a built-in clip holds the wire instead of a separate ligature. They straighten teeth and correct the bite under the orthodontist's control, and adjustments are made without changing a ligature on every bracket.$t$ WHERE id = '7a919a96-d7ba-4d8a-b82e-5d4c2522348a';
UPDATE public.services SET summary = $t$Професійна чистка зубів у клініці Зубна Фея в Білій Церкві видаляє м'який наліт, зубний камінь і пігментацію від кави чи тютюну, зокрема між зубами та біля ясен. Лікар оцінює стан ясен, знімає відкладення професійними інструментами й полірує зуби. Чистка не замінює домашнього догляду і не змінює власний колір емалі.$t$, summary_en = $t$Professional teeth cleaning at Tooth Fairy in Bila Tserkva removes soft plaque, tartar and stains from coffee or tobacco, including between the teeth and along the gums. The dentist checks the gums, removes deposits with professional instruments and polishes the teeth. Cleaning does not replace home care or change the natural shade of enamel.$t$ WHERE id = 'a60c5e50-3662-4602-a566-c09051fc78c8';
UPDATE public.services SET summary = $t$Лікування карієсу в клініці Зубна Фея у Білій Церкві починають з огляду, очищення поверхні та, за потреби, знімка. Лікар прибирає уражені тканини, не забираючи зайвого, і щільно відновлює зуб пломбою. Початковий карієс без порожнини іноді лікують без свердління: фтором, корекцією гігієни або інфільтрацією.$t$, summary_en = $t$Cavity treatment at Tooth Fairy in Bila Tserkva starts with an examination, surface cleaning and an X-ray when needed. The dentist removes only the decayed tissue and restores the tooth with a tight filling. Early decay without a cavity can sometimes be treated without drilling, using fluoride, better oral hygiene or resin infiltration.$t$ WHERE id = '48f95f98-f9a9-4c51-be28-2cbbfc52db26';
UPDATE public.services SET summary = $t$Металокерамічні коронки в клініці Зубна Фея у Білій Церкві відновлюють сильно зруйновані зуби, зуби з великими пломбами, тріщинами або після лікування каналів. Міцний металевий каркас облицьовують керамікою під колір сусідніх зубів. Коронка накриває зуб з усіх боків, повертає йому форму й бере на себе жувальне навантаження.$t$, summary_en = $t$Metal-ceramic crowns at Tooth Fairy in Bila Tserkva restore badly damaged teeth, teeth with large fillings, cracks or after root canal treatment. A strong metal framework is covered with ceramic matched to the neighbouring teeth. The crown covers the whole tooth, restores its shape and takes the chewing load.$t$ WHERE id = '67d6ca0d-21bd-4257-a257-2c36f1f793fd';
UPDATE public.services SET summary = $t$Керамічні коронки в клініці Зубна Фея у Білій Церкві - безметалеві конструкції, які повністю накривають зруйнований або ослаблений зуб. Їх рекомендують при значному руйнуванні, тріщинах, великих пломбах чи після лікування каналів, а також для відновлення форми й кольору передніх зубів. Вид кераміки лікар підбирає під положення зуба та прикус.$t$, summary_en = $t$Ceramic crowns at Tooth Fairy in Bila Tserkva are metal-free restorations that fully cover a damaged or weakened tooth. They are recommended for extensive decay, cracks, large fillings or after root canal treatment, and to restore the shape and colour of front teeth. The type of ceramic is chosen for the tooth position and bite.$t$ WHERE id = '57eaba44-0872-4e13-b1e5-693f8243bec4';
UPDATE public.services SET summary = $t$Видалення зуба в клініці Зубна Фея у Білій Церкві проводять, коли зуб уже неможливо надійно зберегти: перелом кореня, руйнування нижче ясен, втрата кісткової опори чи інфекція. Лікар спочатку оцінює корені й знімок, а потім обирає звичайне або хірургічне видалення. Якщо зуб можна вилікувати, видаляти його не будуть.$t$, summary_en = $t$Tooth extraction at Tooth Fairy in Bila Tserkva is performed when a tooth can no longer be reliably saved, for example with a fractured root, decay below the gum, loss of bone support or infection. The dentist first assesses the roots and X-ray, then chooses a simple or surgical extraction. If the tooth can be treated, it is kept.$t$ WHERE id = '2c3cfe2a-444c-4226-b24c-a424fd33ff4b';
UPDATE public.services SET summary = $t$Видалення зуба мудрості в клініці Зубна Фея у Білій Церкві проводять після огляду та знімка, коли вісімка спричиняє запалення ясен, карієс, кісту чи пошкоджує сусідній зуб. Хірург видаляє і прорізані, і ретиновані або дистоповані зуби, за потреби розділяючи їх на частини. Рівний здоровий зуб мудрості можна залишити.$t$, summary_en = $t$Wisdom tooth removal at Tooth Fairy in Bila Tserkva is done after an examination and X-ray when the tooth causes gum inflammation, decay, a cyst or damages the neighbouring tooth. The surgeon removes erupted, impacted and misaligned wisdom teeth, sectioning them when needed. A straight, healthy wisdom tooth can be kept.$t$ WHERE id = '4927195e-569e-4e46-ba06-f2211633ba82';
UPDATE public.services SET summary = $t$Відбілювання зубів у клініці Зубна Фея у Білій Церкві змінює внутрішній колір емалі, який потемнів від кави, чаю, тютюну або з віком. Активний гель освітлює пігменти, зуби при цьому не сточують і не фарбують. Перед процедурою стоматолог оглядає емаль і ясна, а за потреби спочатку проводить професійну чистку.$t$, summary_en = $t$Teeth whitening at Tooth Fairy in Bila Tserkva lightens the natural colour of enamel that has darkened from coffee, tea, tobacco or age. An active gel breaks down pigments without grinding or coating the teeth. Before whitening, the dentist checks the enamel and gums and carries out a professional cleaning first if needed.$t$ WHERE id = 'd5a2c035-0f8d-4b04-8fa8-98aa073097a9';
UPDATE public.services SET summary = $t$Реставрація зубів у клініці Зубна Фея в Білій Церкві повертає зубам природну форму, відтінок і щільний контакт із сусідніми. Лікар відновлює композитом сколи, стерті краї, невеликі тріщини та старі пломби, а також коригує форму зуба чи закриває невеликий проміжок. На передніх зубах важлива естетика, на жувальних - функція.$t$, summary_en = $t$Tooth restoration at Tooth Fairy in Bila Tserkva brings back the natural shape, shade and tight contact between teeth. The dentist uses composite to repair chips, worn edges, small cracks and old fillings, and to reshape a tooth or close a small gap. Front teeth focus on appearance, back teeth on chewing function.$t$ WHERE id = 'a5fa7020-e1e3-4287-954e-aa534d98e5da';
UPDATE public.services SET summary = $t$Керамічні вініри в клініці Зубна Фея у Білій Церкві - тонкі індивідуальні пластинки, які фіксують на передню поверхню зубів. Вони змінюють колір, форму й пропорції усмішки, закривають сколи, нерівні краї, проміжки та старі пломби. Перед виготовленням стоматолог оцінює прикус і стан емалі, бо вінір потребує надійної основи.$t$, summary_en = $t$Ceramic veneers at Tooth Fairy in Bila Tserkva are thin custom shells bonded to the front surface of the teeth. They change the colour, shape and proportions of a smile and cover chips, uneven edges, gaps and old fillings. Before making them, the dentist checks the bite and enamel, because a veneer needs a reliable base.$t$ WHERE id = '2e58f576-b7ea-4a50-8260-15451d8f7515';
